contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 limit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (limit) + (limit)); require(limit <= 1000000000000000000000000000000);
        require(limit > 0);
        require(address(this).balance >= limit);

        c.AdjustBetAmounts(limit); if (__ESBMC_reverted()) return;
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.wager{value: limit}(); if (__ESBMC_reverted()) return;

        bool wagered = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        bool secondReverted;
        c.wager{value: limit}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { secondReverted = true; } else { secondReverted = false; }

        assert(wagered && secondReverted);
    }

    receive() external payable {}
}

